import json,sqlite3
db=sqlite3.connect(__import__('pathlib').Path(__file__).resolve().parent/'state.sqlite3')
run=db.execute('select run_id from engine_runs order by started desc limit 1').fetchone()[0]
print(json.dumps({'run':run,'api_counts':db.execute("select provider,outcome,count(*) from http_attempts where run_id=? and stage='resolve' group by provider,outcome",(run,)).fetchall(),'pmc_requests':db.execute("select url,outcome,http_status,bytes,error from http_attempts where run_id=? and stage='resolve' and provider='pmc_cloud' limit 12",(run,)).fetchall(),'crosscheck_yields':db.execute("select json_extract(payload,'$.provider'),sum(json_extract(payload,'$.new_locations')),count(*) from events where kind='oa_crosscheck' and json_extract(payload,'$.run_id')=? group by json_extract(payload,'$.provider')",(run,)).fetchall(),'recovered_downloads':db.execute("select l.provenance,count(*) from http_attempts a join download_locations l on a.paper_id=l.paper_id and a.url=l.url where a.run_id=? and a.outcome='success' and a.stage='download' group by l.provenance",(run,)).fetchall(),'failures':db.execute("select provider,outcome,error from http_attempts where run_id=? and stage='download' and outcome<>'success' limit 12",(run,)).fetchall()},ensure_ascii=False))
